/// <summary>
/// PricingAttribute of table <c>METInventItemOrderSetup</c> field ItemType.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(METInventItemOrderSetup, ItemType))]
internal class METGUPPricingAttributeMETInventItemOrderSetupItemType extends METGUPPricingAttributeMETInventItemOrderSetup implements GUPIPricingAttribute
{
}

Method.Source:
/// <summary>
/// Get value of the attribute
/// </summary>
/// <param name = "_pricingObject">Common</param>
/// <returns>anytype</returns>
public anytype getValueOfAttribute(Common _pricingObject)
{
    return this.getTableRecord(_pricingObject).ItemType;
}

/// <summary>
/// Retuns the name of the attribute
/// </summary>
/// <returns>name of attribute</returns>
public str getName()
{
    return fieldPName(METInventItemOrderSetup, ItemType);
}

/// <summary>
/// Get attribte data type
/// </summary>
/// <returns>AttributeDataType</returns>
public AttributeDataType getDataType()
{
    return AttributeDataType::Text;
}

/// <summary>
/// Provide correct table path.
/// </summary>
/// <returns>The table field path if table field exists; otherwise 'PATH_NOT_EXIST'.</returns>
public GUPPricingAttributeTableFieldPath getPath()
{
    return METConstants::pathNotExist;
}

/// This method added on 12/03/2025 - Include description in lookup
/// <summary>
/// specify the list of values applicable
/// </summary>
/// <returns><c>Set</c> object</returns>
public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    METItemType     metItemType;

    while select metItemType
        group by ItemType, Description
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(metItemType.ItemType, metItemType.Description);
        ret.add(valueObject);
    }

    return ret;
}
